// Plus Two entrance chemistry bank: Structure of the atom. Original fibub questions.
// Constants used: R_H energy 13.6 eV (2.18 × 10^-18 J), h = 6.626 × 10^-34 J s, hc = 1240 eV nm, c = 3 × 10^8 m/s, 1 eV = 1.6 × 10^-19 J, a0 = 0.529 Å, m_e = 9.1 × 10^-31 kg.
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
/** single-answer mcq; the correct option goes to a rotating position so answers spread evenly */
const mk = (id, level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id, type: 'mcq', level, format: 'single', exams: EX[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (id, level, sub, q, answer, tol, unit, sol, trap) => ({ id, type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
const msq = (id, level, sub, q, options, answer, sol, trap) => ({ id, type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (id, level, sub, A, R, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'assertion', exams: EX[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const mat = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (id, level, sub, group, q, answer, tol, unit, sol, trap) => ({ ...nat(id, level, sub, q, answer, tol, unit, sol, trap), format: 'passage', group });

export default {
  topic: 'atomic-structure',
  groups: {
    m1: { title: 'Match the scientist with the discovery', list1: ['A. J. J. Thomson', 'B. Rutherford', 'C. Chadwick', 'D. Millikan'], list2: ['p. The atomic nucleus (from alpha-particle scattering)', 'q. The charge-to-mass ratio of the electron', 'r. The charge on the electron (oil-drop experiment)', 's. The neutron'] },
    m2: { title: 'Match the quantum number with what it tells', list1: ['A. Principal quantum number n', 'B. Azimuthal quantum number l', 'C. Magnetic quantum number m<sub>l</sub>', 'D. Spin quantum number m<sub>s</sub>'], list2: ['p. Shape of the orbital', 'q. Orientation of the orbital in space', 'r. Size and (in a hydrogen atom) energy of the orbital', 's. Direction of the spin of the electron'] },
    m3: { title: 'Match the orbital with its nodes', list1: ['A. 3s', 'B. 3p', 'C. 3d', 'D. 4s'], list2: ['p. 0 radial nodes and 2 angular nodes', 'q. 1 radial node and 1 angular node', 'r. 2 radial nodes and 0 angular nodes', 's. 3 radial nodes and 0 angular nodes'] },
    p1: { title: 'A one-electron ion', passage: '<p>A hydrogen-like ion X<sup>(Z-1)+</sup> has only one electron. Its ground-state energy is <b>-54.4 eV</b>. Take the ground-state energy of hydrogen as -13.6 eV and hc = 1240 eV nm.</p>' },
    p2: { title: 'Photoelectric effect on a metal', passage: '<p>Light of wavelength <b>400 nm</b> falls on a metal surface whose work function is <b>2.3 eV</b>. Take hc = 1240 eV nm, 1 eV = 1.6 × 10<sup>-19</sup> J and the electron mass 9.1 × 10<sup>-31</sup> kg.</p>' },
    p3: { title: 'An iron compound', passage: '<p>Iron has atomic number 26. In an experiment, a student studies the magnetic behaviour of two ions of iron, Fe<sup>2+</sup> and Fe<sup>3+</sup>, in the gaseous state.</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    mk('as-001', 1, 'subatomic particles', 'J. J. Thomson\'s cathode-ray experiment led to the discovery of the', 'electron', ['proton', 'neutron', 'nucleus'], '<p>Cathode rays are streams of electrons. Thomson measured their charge-to-mass ratio (e/m) and showed they are a part of every atom. The proton was found by Goldstein\'s canal rays and Rutherford, the neutron by Chadwick.</p>'),
    mk('as-002', 1, 'Rutherford model', 'In Rutherford\'s alpha-particle scattering experiment, most alpha particles passed straight through the gold foil. This showed that', 'most of the atom is empty space', ['the atom is a uniform positive sphere', 'electrons are heavier than alpha particles', 'the nucleus is negatively charged'], '<p>Most particles went straight through, so most of the atom is empty space. A few bounced back at large angles: a small, dense, positively charged nucleus.</p><p>A uniform positive sphere (Thomson) would not scatter alpha particles to large angles.</p>'),
    mk('as-003', 1, 'subatomic particles', 'The numbers of protons, neutrons and electrons in <sup>23</sup><sub>11</sub>Na are respectively', '11, 12, 11', ['11, 23, 11', '12, 11, 12', '23, 11, 23'], '<p>Protons = atomic number = 11. Electrons in the neutral atom = 11. Neutrons = mass number - atomic number = 23 - 11 = <b>12</b>.</p>'),
    mk('as-004', 1, 'quantum numbers', 'The maximum number of electrons that can be accommodated in the shell with n = 3 is', '18', ['8', '9', '32'], '<p>Capacity of a shell = 2n<sup>2</sup> = 2 × 9 = <b>18</b>.</p><p>8 is the capacity of n = 2 and 32 of n = 4.</p>'),
    mk('as-005', 1, 'quantum numbers', 'The azimuthal quantum number l for a p subshell is', '1', ['0', '2', '3'], '<p>l = 0 is s, l = 1 is p, l = 2 is d, l = 3 is f. So a p subshell has <b>l = 1</b> (three orbitals, m<sub>l</sub> = -1, 0, +1).</p>'),
    mk('as-006', 1, 'orbitals', 'How many orbitals are present in a d subshell?', '5', ['3', '7', '10'], '<p>For d, l = 2, so m<sub>l</sub> = -2, -1, 0, +1, +2: <b>5</b> orbitals (number of orbitals = 2l + 1).</p><p>10 is the number of <i>electrons</i> in a d subshell.</p>'),
    mk('as-007', 1, 'electronic configuration', 'The electronic configuration of sodium (Z = 11) is', '1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>1</sup>', ['1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>5</sup> 3s<sup>2</sup>', '1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3p<sup>1</sup>', '1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>7</sup> 3s<sup>0</sup>'], '<p>Fill in the order 1s, 2s, 2p, 3s: 2 + 2 + 6 = 10 electrons, and the eleventh goes into 3s. A 2p subshell holds at most 6 electrons, and 3s fills before 3p.</p>'),
    mk('as-008', 1, 'quantum numbers', 'Which quantum number decides the shape of an orbital?', 'Azimuthal quantum number (l)', ['Principal quantum number (n)', 'Magnetic quantum number (m<sub>l</sub>)', 'Spin quantum number (m<sub>s</sub>)'], '<p>n gives size and energy. <b>l gives shape</b> (s spherical, p dumbbell, d cloverleaf). m<sub>l</sub> gives orientation. m<sub>s</sub> gives spin direction.</p>'),
    mk('as-009', 1, 'Pauli principle', 'According to the Pauli exclusion principle,', 'no two electrons in an atom can have all four quantum numbers the same', ['electrons fill orbitals of the same energy singly first', 'electrons fill the lowest energy orbital first', 'the position and momentum of an electron cannot both be known exactly'], '<p>Pauli: no two electrons in one atom can have the same set of n, l, m<sub>l</sub>, m<sub>s</sub>. So an orbital holds at most two electrons, with opposite spins.</p><p>The other options are Hund\'s rule, the Aufbau principle and Heisenberg\'s uncertainty principle.</p>'),
    nat('as-010', 1, 'electromagnetic radiation', 'The frequency of light of wavelength 600 nm is x × 10<sup>14</sup> Hz. Find x. (c = 3 × 10<sup>8</sup> m s<sup>-1</sup>)', 5, 0, '', '<p>ν = c / λ. λ = 600 nm = 6 × 10<sup>-7</sup> m.</p><p>ν = 3 × 10<sup>8</sup> / 6 × 10<sup>-7</sup> = 5 × 10<sup>14</sup> Hz, so x = <b>5</b>.</p>'),
    mk('as-011', 1, 'Bohr model', 'The energy of the electron in the ground state of a hydrogen atom is', '-13.6 eV', ['+13.6 eV', '-3.4 eV', '0 eV'], '<p>E<sub>n</sub> = -13.6 / n<sup>2</sup> eV. For n = 1: <b>-13.6 eV</b>. The negative sign means the electron is bound. Zero is the energy at n = infinity (free electron).</p>'),
    // ---------- Level 2 ----------
    mk('as-012', 2, 'Bohr model', 'The radius of the second Bohr orbit of hydrogen is (a<sub>0</sub> = 0.529 Å)', '2.116 Å', ['1.058 Å', '0.529 Å', '4.761 Å'], '<p>r<sub>n</sub> = 0.529 n<sup>2</sup> / Z Å. For H, Z = 1 and n = 2: 0.529 × 4 = <b>2.116 Å</b>.</p><p>1.058 Å wrongly uses r ∝ n; 4.761 Å is for n = 3.</p>'),
    mk('as-013', 2, 'Bohr model', 'The energy of the electron in the n = 2 level of He<sup>+</sup> is', '-13.6 eV', ['-3.4 eV', '-54.4 eV', '-6.8 eV'], '<p>E<sub>n</sub> = -13.6 Z<sup>2</sup> / n<sup>2</sup>. With Z = 2 and n = 2: -13.6 × 4 / 4 = <b>-13.6 eV</b>.</p><p>-3.4 eV is for H, n = 2 (Z not squared in). -54.4 eV is for He<sup>+</sup>, n = 1.</p>', 'Z is squared in the energy.'),
    nat('as-014', 2, 'orbitals and nodes', 'How many radial nodes does a 3s orbital have?', 2, 0, '', '<p>Radial nodes = n - l - 1 = 3 - 0 - 1 = <b>2</b>.</p>'),
    nat('as-015', 2, 'Hund\'s rule', 'How many unpaired electrons are present in a nitrogen atom (1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>3</sup>) in its ground state?', 3, 0, '', '<p>The three 2p electrons go into three different 2p orbitals with parallel spins (Hund\'s rule), so there are <b>3</b> unpaired electrons.</p>'),
    mk('as-016', 2, 'electronic configuration', 'The ground-state electronic configuration of chromium (Z = 24) is', '[Ar] 3d<sup>5</sup> 4s<sup>1</sup>', ['[Ar] 3d<sup>4</sup> 4s<sup>2</sup>', '[Ar] 3d<sup>6</sup>', '[Ar] 4s<sup>2</sup> 4p<sup>4</sup>'], '<p>A half-filled d subshell (3d<sup>5</sup>) gets extra stability from exchange energy and symmetry. So one electron moves from 4s to 3d: [Ar] 3d<sup>5</sup> 4s<sup>1</sup>.</p>'),
    mk('as-017', 2, 'electronic configuration', 'Which is the ground-state configuration of copper (Z = 29)?', '[Ar] 3d<sup>10</sup> 4s<sup>1</sup>', ['[Ar] 3d<sup>9</sup> 4s<sup>2</sup>', '[Ar] 3d<sup>8</sup> 4s<sup>2</sup> 4p<sup>1</sup>', '[Ar] 3d<sup>10</sup> 4s<sup>2</sup>'], '<p>A completely filled d subshell is extra stable, so one 4s electron goes to 3d: [Ar] 3d<sup>10</sup> 4s<sup>1</sup>. [Ar] 3d<sup>10</sup> 4s<sup>2</sup> would be 30 electrons (zinc).</p>'),
    mk('as-018', 2, 'quantum numbers', 'Which set of quantum numbers (n, l, m<sub>l</sub>, m<sub>s</sub>) is NOT possible for an electron?', '(2, 2, 0, +½)', ['(3, 2, -1, +½)', '(2, 1, 0, -½)', '(1, 0, 0, +½)'], '<p>For a given n, l runs from 0 to n - 1. With n = 2, l can be 0 or 1 only. So l = 2 is <b>not allowed</b>. All other sets obey: l &lt; n, |m<sub>l</sub>| ≤ l, m<sub>s</sub> = ±½.</p>', 'Check l &lt; n first.'),
    nat('as-019', 2, 'Bohr model', 'An electron in a hydrogen atom is excited to n = 4. What is the maximum number of different spectral lines it can give when it returns to lower levels?', 6, 0, '', '<p>Number of lines = n(n - 1)/2 = 4 × 3 / 2 = <b>6</b>.</p><p>They are 4→3, 4→2, 4→1, 3→2, 3→1, 2→1.</p>'),
    mk('as-020', 2, 'spectral series', 'The Balmer series of hydrogen contains lines from transitions that end at', 'n = 2, and lies in the visible region', ['n = 1, and lies in the ultraviolet', 'n = 3, and lies in the infrared', 'n = 2, and lies in the ultraviolet'], '<p>Lyman: ends at n = 1 (UV). <b>Balmer: ends at n = 2 (visible)</b>. Paschen: ends at n = 3 (IR). Brackett: n = 4, Pfund: n = 5.</p>'),
    nat('as-021', 2, 'photoelectric effect', 'Light of wavelength 200 nm falls on a metal whose work function is 4.2 eV. What is the maximum kinetic energy of the emitted photoelectrons in eV? (hc = 1240 eV nm)', 2, 0.02, 'eV', '<p>Photon energy = 1240 / 200 = 6.2 eV.</p><p>K<sub>max</sub> = hν - φ = 6.2 - 4.2 = <b>2.0 eV</b>.</p>'),
    nat('as-022', 2, 'de Broglie wavelength', 'An electron is accelerated from rest through 100 V. What is its de Broglie wavelength in Å? Use λ = 12.27 / √V Å.', 1.23, 0.02, 'Å', '<p>λ = 12.27 / √V = 12.27 / 10 = <b>1.23 Å</b>.</p><p>(Derivation: λ = h / √(2meV).)</p>'),
    mk('as-023', 2, 'magnetic moment', 'The spin-only magnetic moment of Fe<sup>3+</sup> (Z = 26) is closest to', '5.92 BM', ['4.90 BM', '3.87 BM', '2.83 BM'], '<p>Fe<sup>3+</sup> is [Ar] 3d<sup>5</sup>, so n = 5 unpaired electrons.</p><p>μ = √(n(n + 2)) = √35 = <b>5.92 BM</b>.</p><p>4.90 BM is n = 4 (Fe<sup>2+</sup>); 3.87 BM is n = 3.</p>', 'Remove 4s electrons first when forming the cation.'),
    mk('as-024', 2, 'magnetic moment', 'The spin-only magnetic moment of Ti<sup>3+</sup> (Z = 22) is', '1.73 BM', ['0 BM', '2.83 BM', '1.41 BM'], '<p>Ti is [Ar] 3d<sup>2</sup> 4s<sup>2</sup>. Ti<sup>3+</sup> loses 4s<sup>2</sup> and one 3d electron: [Ar] 3d<sup>1</sup>.</p><p>n = 1, μ = √(1 × 3) = <b>1.73 BM</b>.</p>'),
    nat('as-025', 2, 'electromagnetic radiation', 'What is the energy of a photon of wavelength 500 nm in eV? (hc = 1240 eV nm) Give the answer to 2 decimals.', 2.48, 0.02, 'eV', '<p>E = hc / λ = 1240 / 500 = <b>2.48 eV</b>.</p>'),
    nat('as-026', 2, 'magnetic moment', 'How many unpaired electrons does Fe<sup>2+</sup> (Z = 26) have?', 4, 0, '', '<p>Fe: [Ar] 3d<sup>6</sup> 4s<sup>2</sup>. Fe<sup>2+</sup> loses the two 4s electrons: [Ar] 3d<sup>6</sup>.</p><p>In 3d<sup>6</sup> one orbital is paired (↑↓) and four have one electron each. Unpaired = <b>4</b>.</p>'),
    mk('as-027', 2, 'electronic configuration', 'Which of the following species has the same number of electrons as a neon atom?', 'Mg<sup>2+</sup>', ['Mg<sup>+</sup>', 'Cl<sup>-</sup>', 'K<sup>+</sup>'], '<p>Ne has 10 electrons. Mg<sup>2+</sup>: 12 - 2 = 10 ✓. Mg<sup>+</sup>: 11. Cl<sup>-</sup>: 18. K<sup>+</sup>: 18.</p>'),
    mk('as-028', 2, 'Aufbau principle', 'In a neutral atom, which subshell is filled after 4s according to the Aufbau principle?', '3d', ['4p', '4d', '5s'], '<p>The order of filling follows increasing (n + l): 4s (4) &lt; 3d (5) &lt; 4p (5) &lt; 5s (5). Between equal n + l, the lower n goes first, so 3d fills before 4p.</p><p>So after 4s comes <b>3d</b>.</p>'),
    stm('as-029', 2, 'orbitals', 'An s orbital is spherically symmetrical.', 'An s orbital has no angular node.', 0, '<p>Both are correct. For l = 0 the number of angular nodes = l = 0, so the probability depends only on the distance from the nucleus: spherical symmetry.</p>'),
    asr('as-030', 2, 'Bohr model', 'The electron in a stable Bohr orbit does not fall into the nucleus.', 'An electron in a stable orbit does not radiate energy.', 0, '<p>This is Bohr\'s postulate: in a stationary orbit the electron does not lose energy, so it does not spiral inward. A and R are true, and R explains A.</p><p>(Classical physics says an orbiting charge would radiate and collapse into the nucleus. That is the failure Bohr fixed.)</p>'),
    // ---------- Level 3 ----------
    nat('as-031', 3, 'spectral series', 'What is the wavelength of the first line of the Lyman series of hydrogen, in nm? (R<sub>H</sub> = 1.097 × 10<sup>7</sup> m<sup>-1</sup>)', 121.5, 0.5, 'nm', '<p>First Lyman line: n = 2 → 1. 1/λ = R(1/1<sup>2</sup> - 1/2<sup>2</sup>) = R × 3/4.</p><p>λ = 4 / (3R) = 4 / (3 × 1.097 × 10<sup>7</sup>) = 1.215 × 10<sup>-7</sup> m = <b>121.5 nm</b> (ultraviolet).</p>'),
    mk('as-032', 3, 'spectral series', 'The longest wavelength line in the Balmer series of hydrogen (R<sub>H</sub> = 1.097 × 10<sup>7</sup> m<sup>-1</sup>) is close to', '656 nm', ['486 nm', '122 nm', '1875 nm'], '<p>Longest wavelength means lowest energy gap: n = 3 → 2. 1/λ = R(1/4 - 1/9) = 5R/36.</p><p>λ = 36 / (5 × 1.097 × 10<sup>7</sup>) = 6.56 × 10<sup>-7</sup> m = <b>656 nm</b>.</p><p>486 nm is n = 4 → 2, 122 nm is the Lyman line, 1875 nm is the Paschen α line (4 → 3).</p>', 'Longest wavelength = smallest energy difference.'),
    mk('as-033', 3, 'Bohr model', 'The energy needed to remove the electron from a hydrogen atom that is in the n = 2 level is', '3.4 eV', ['13.6 eV', '10.2 eV', '6.8 eV'], '<p>E<sub>2</sub> = -13.6 / 4 = -3.4 eV. To ionise (reach E = 0), supply <b>3.4 eV</b>.</p><p>13.6 eV is for n = 1. 10.2 eV is the energy to go from n = 1 to n = 2.</p>'),
    mk('as-034', 3, 'Bohr model', 'The energy required to remove the electron from a ground-state He<sup>+</sup> ion is', '54.4 eV', ['13.6 eV', '27.2 eV', '108.8 eV'], '<p>Ionisation energy = 13.6 Z<sup>2</sup> / n<sup>2</sup> = 13.6 × 4 / 1 = <b>54.4 eV</b>.</p><p>27.2 eV uses Z instead of Z<sup>2</sup>; 108.8 eV uses Z<sup>3</sup>.</p>'),
    nat('as-035', 3, 'Bohr model', 'The speed of the electron in the second Bohr orbit of Li<sup>2+</sup> is x × 10<sup>6</sup> m s<sup>-1</sup>. Find x to 2 decimals. (Speed in the first orbit of H = 2.18 × 10<sup>6</sup> m s<sup>-1</sup>)', 3.27, 0.03, '× 10<sup>6</sup> m s<sup>-1</sup>', '<p>v<sub>n</sub> = 2.18 × 10<sup>6</sup> × Z / n m s<sup>-1</sup>.</p><p>For Li<sup>2+</sup>, Z = 3, n = 2: v = 2.18 × 10<sup>6</sup> × 3 / 2 = <b>3.27 × 10<sup>6</sup></b> m s<sup>-1</sup>.</p>'),
    mk('as-036', 3, 'de Broglie wavelength', 'In the third Bohr orbit (n = 3) of a hydrogen atom, how many de Broglie wavelengths of the electron fit around the circumference?', '3', ['1', '9', '2π'], '<p>Bohr\'s condition mvr = nh/2π is the same as 2πr = nλ, where λ = h/mv.</p><p>So the circumference equals n wavelengths: <b>3</b>.</p>', 'It is n wavelengths, not n<sup>2</sup>.'),
    nat('as-037', 3, 'orbitals and nodes', 'What is the total number of nodes (radial + angular) in a 4d orbital?', 3, 0, '', '<p>Radial nodes = n - l - 1 = 4 - 2 - 1 = 1. Angular nodes = l = 2.</p><p>Total = 1 + 2 = <b>3</b> (this is always n - 1).</p>'),
    nat('as-038', 3, 'quantum numbers', 'How many electrons in an atom can have the quantum numbers n = 3 and m<sub>l</sub> = 0?', 6, 0, '', '<p>For n = 3, l = 0, 1, 2. Each l has exactly one orbital with m<sub>l</sub> = 0 (3s, 3p<sub>z</sub>, 3d<sub>z²</sub>): 3 orbitals.</p><p>Each holds 2 electrons: 3 × 2 = <b>6</b>.</p>', 'Count orbitals with m<sub>l</sub> = 0 first, then double.'),
    nat('as-039', 3, 'quantum numbers', 'How many electrons in a chromium atom (Z = 24) have azimuthal quantum number l = 1?', 12, 0, '', '<p>Cr: 1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup> 3d<sup>5</sup> 4s<sup>1</sup>.</p><p>l = 1 means p electrons: 2p<sup>6</sup> + 3p<sup>6</sup> = <b>12</b>.</p>'),
    nat('as-040', 3, 'photoelectric effect', 'Light of wavelength 250 nm falls on a metal with a work function of 2.2 eV. What is the stopping potential in volts? (hc = 1240 eV nm)', 2.76, 0.03, 'V', '<p>Photon energy = 1240 / 250 = 4.96 eV.</p><p>K<sub>max</sub> = 4.96 - 2.2 = 2.76 eV. Stopping potential V<sub>0</sub> = K<sub>max</sub> / e = <b>2.76 V</b>.</p>'),
    mk('as-041', 3, 'photoelectric effect', 'Light above the threshold frequency falls on a metal. The intensity of the light is doubled, with the frequency kept the same. Which statement is correct?', 'The number of photoelectrons per second doubles and the maximum kinetic energy stays the same', ['The maximum kinetic energy doubles and the number of photoelectrons stays the same', 'Both the number of photoelectrons and the maximum kinetic energy double', 'No photoelectrons are emitted'], '<p>Intensity means the number of photons per second. Twice as many photons eject twice as many electrons (one photon, one electron).</p><p>K<sub>max</sub> = hν - φ depends on frequency only, so it does not change.</p>', 'Intensity controls the number, frequency controls the energy.'),
    nat('as-042', 3, 'electromagnetic radiation', 'A 100 W lamp gives out all its power as light of wavelength 600 nm. Find the number of photons emitted per second, as x × 10<sup>20</sup>. Give x to 2 decimals. (h = 6.626 × 10<sup>-34</sup> J s, c = 3 × 10<sup>8</sup> m s<sup>-1</sup>)', 3.02, 0.03, '', '<p>Energy of one photon = hc/λ = 6.626 × 10<sup>-34</sup> × 3 × 10<sup>8</sup> / 6 × 10<sup>-7</sup> = 3.313 × 10<sup>-19</sup> J.</p><p>Photons per second = 100 / 3.313 × 10<sup>-19</sup> = 3.02 × 10<sup>20</sup>, so x = <b>3.02</b>.</p>'),
    nat('as-043', 3, 'de Broglie wavelength', 'A cricket ball of mass 0.15 kg moves at 40 m s<sup>-1</sup>. Its de Broglie wavelength is x × 10<sup>-34</sup> m. Find x to 2 decimals. (h = 6.626 × 10<sup>-34</sup> J s)', 1.1, 0.02, '', '<p>λ = h / (mv) = 6.626 × 10<sup>-34</sup> / (0.15 × 40) = 6.626 × 10<sup>-34</sup> / 6 = <b>1.10 × 10<sup>-34</sup> m</b>.</p><p>This is far too small to observe, so the wave nature of everyday objects is never noticed.</p>'),
    mk('as-044', 3, 'magnetic moment', 'Which of the following ions is diamagnetic? (Z: Ti 22, Fe 26, Cu 29)', 'Cu<sup>+</sup>', ['Cu<sup>2+</sup>', 'Fe<sup>2+</sup>', 'Ti<sup>3+</sup>'], '<p>Cu<sup>+</sup> is [Ar] 3d<sup>10</sup>: all electrons are paired, so it is diamagnetic.</p><p>Cu<sup>2+</sup> is 3d<sup>9</sup> (1 unpaired), Fe<sup>2+</sup> is 3d<sup>6</sup> (4 unpaired), Ti<sup>3+</sup> is 3d<sup>1</sup> (1 unpaired).</p>'),
    nat('as-045', 3, 'magnetic moment', 'How many unpaired electrons are present in Cr<sup>3+</sup> (Z = 24)?', 3, 0, '', '<p>Cr is [Ar] 3d<sup>5</sup> 4s<sup>1</sup>. Cr<sup>3+</sup> loses the 4s electron and two 3d electrons: [Ar] 3d<sup>3</sup>.</p><p>Three electrons in three different d orbitals: <b>3</b> unpaired.</p>', 'Cr is an exception: remove 4s first, then 3d.'),
    mk('as-046', 3, 'magnetic moment', 'An ion has a spin-only magnetic moment of 3.87 BM. Which one could it be? (Z: Ti 22, Cr 24, Mn 25, Fe 26)', 'Cr<sup>3+</sup>', ['Ti<sup>3+</sup>', 'Mn<sup>2+</sup>', 'Fe<sup>3+</sup>'], '<p>μ = √(n(n + 2)) = 3.87 gives n = 3 unpaired electrons.</p><p>Cr<sup>3+</sup> (3d<sup>3</sup>): n = 3 ✓. Ti<sup>3+</sup>: n = 1. Mn<sup>2+</sup> (3d<sup>5</sup>): n = 5. Fe<sup>3+</sup> (3d<sup>5</sup>): n = 5.</p>'),
    mk('as-047', 3, 'Aufbau principle', 'Which is the correct order of increasing energy for the orbitals 3d, 4p and 5s in a multi-electron atom?', '3d &lt; 4p &lt; 5s', ['4p &lt; 3d &lt; 5s', '5s &lt; 4p &lt; 3d', '3d &lt; 5s &lt; 4p'], '<p>Use the (n + l) rule: 3d = 3 + 2 = 5; 4p = 4 + 1 = 5; 5s = 5 + 0 = 5. All are equal, so the one with the lower n has the lower energy.</p><p>Order: 3d (n = 3) &lt; 4p (n = 4) &lt; 5s (n = 5).</p>', 'When (n + l) ties, the lower n is lower in energy.'),
    mk('as-048', 3, 'Bohr model', 'The energy of the electron in the ground state of Li<sup>2+</sup> is', '-122.4 eV', ['-40.8 eV', '-13.6 eV', '-27.2 eV'], '<p>E = -13.6 Z<sup>2</sup> / n<sup>2</sup> = -13.6 × 9 / 1 = <b>-122.4 eV</b>.</p><p>-40.8 eV uses Z = 3 without squaring.</p>'),
    nat('as-049', 3, 'Bohr model', 'What is the ratio of the radius of the n = 2 orbit of He<sup>+</sup> to the radius of the n = 1 orbit of H?', 2, 0, '', '<p>r ∝ n<sup>2</sup> / Z.</p><p>He<sup>+</sup>, n = 2: 4 / 2 = 2. H, n = 1: 1 / 1 = 1. Ratio = <b>2</b>.</p>'),
    nat('as-050', 3, 'spectral series', 'What is the wavelength, in nm, of the series limit of the Lyman series of hydrogen? (R<sub>H</sub> = 1.097 × 10<sup>7</sup> m<sup>-1</sup>)', 91.2, 0.5, 'nm', '<p>Series limit: transition from n = ∞ to n = 1. 1/λ = R(1 - 0) = R.</p><p>λ = 1/R = 1 / 1.097 × 10<sup>7</sup> = 9.116 × 10<sup>-8</sup> m = <b>91.2 nm</b>. It is the shortest wavelength of the series.</p>', 'The series limit is the shortest wavelength, not the longest.'),
    nat('as-051', 3, 'spectral series', 'Hydrogen atoms are excited to the n = 6 level. How many different lines of the Balmer series (transitions ending at n = 2) can they emit?', 4, 0, '', '<p>Balmer lines end at n = 2, and start from n = 3, 4, 5 or 6.</p><p>6→2, 5→2, 4→2, 3→2: <b>4</b> lines.</p>', 'Do not use n(n - 1)/2: that counts all series, not only the Balmer.'),
    mk('as-052', 3, 'Bohr model', 'In the n = 2 orbit of a hydrogen atom, the kinetic energy and the potential energy of the electron are respectively', '+3.4 eV and -6.8 eV', ['-3.4 eV and +6.8 eV', '+6.8 eV and -3.4 eV', '+3.4 eV and -3.4 eV'], '<p>Total energy E = -3.4 eV. In a Bohr orbit KE = -E = +3.4 eV, and PE = 2E = -6.8 eV (KE + PE = E).</p>', 'KE is always positive and equal to the magnitude of the total energy.'),
    nat('as-053', 3, 'Bohr model', 'A hydrogen atom in the ground state absorbs a photon of energy 12.75 eV. To which level is the electron excited?', 4, 0, '', '<p>New energy = -13.6 + 12.75 = -0.85 eV.</p><p>-13.6 / n<sup>2</sup> = -0.85 gives n<sup>2</sup> = 16, so n = <b>4</b>.</p>'),
    nat('as-054', 3, 'orbitals', 'The orbital angular momentum of an electron in a p orbital is x (h / 2π). Find x to 2 decimals.', 1.41, 0.01, '', '<p>L = √(l(l + 1)) × h/2π. For a p orbital l = 1: √2 = <b>1.41</b>.</p>', 'This is not the Bohr value nh/2π.'),
    nat('as-055', 3, 'Bohr model', 'An electron in a hydrogen atom is in an orbit of radius 8.464 Å. Find its principal quantum number. (a<sub>0</sub> = 0.529 Å)', 4, 0, '', '<p>r = 0.529 n<sup>2</sup> Å. So n<sup>2</sup> = 8.464 / 0.529 = 16.</p><p>n = <b>4</b>.</p>'),
    nat('as-056', 3, 'photoelectric effect', 'Light of wavelength 80 nm ionises a hydrogen atom in its ground state. What is the kinetic energy of the ejected electron in eV? (hc = 1240 eV nm, ionisation energy of H = 13.6 eV)', 1.9, 0.02, 'eV', '<p>Photon energy = 1240 / 80 = 15.5 eV.</p><p>K = 15.5 - 13.6 = <b>1.9 eV</b>.</p>'),
    nat('as-057', 3, 'quantum numbers', 'How many electrons in an atom can have n = 4, l = 2 and m<sub>s</sub> = +½?', 5, 0, '', '<p>n = 4, l = 2 is the 4d subshell: m<sub>l</sub> = -2 to +2, so 5 orbitals.</p><p>Each orbital has only one electron with m<sub>s</sub> = +½. So <b>5</b>.</p>'),
    mk('as-058', 3, 'Bohr model', 'Photons of energy 11 eV fall on hydrogen atoms in their ground state. According to Bohr\'s theory,', 'the photons are not absorbed, because 11 eV does not equal any E<sub>n</sub> - E<sub>1</sub>', ['the electron is excited to n = 2 and the extra 0.8 eV is lost as heat', 'the atom is ionised', 'the electron is excited to n = 3'], '<p>A bound electron absorbs a photon only if its energy exactly matches a level gap. From n = 1 the gaps are 10.2 eV (to n = 2), 12.09 eV (n = 3), 12.75 eV (n = 4) and 13.6 eV (ionisation).</p><p>11 eV matches none of them, so <b>it is not absorbed</b>. (A photon above 13.6 eV can ionise, since the free electron may take any extra energy.)</p>', 'Bound-to-bound transitions need exact energies; ionisation needs at least 13.6 eV.'),
    mk('as-059', 3, 'Bohr model', 'Which of the following is NOT correct about Bohr\'s model of the atom?', 'It correctly explains the spectra of all atoms that have two electrons', ['Angular momentum of the electron is quantised as nh/2π', 'The energy of the electron is quantised', 'It explains the spectra of H, He<sup>+</sup> and Li<sup>2+</sup>'], '<p>Bohr\'s model works for one-electron species only (H, He<sup>+</sup>, Li<sup>2+</sup>, ...). It cannot handle electron-electron repulsion, so it fails for atoms such as He. It also cannot explain the Zeeman effect or fine structure.</p><p>The other three are true statements of the model.</p>', 'The model needs exactly one electron, not just "few electrons".'),
    asr('as-060', 3, 'photoelectric effect', 'Increasing the intensity of light above the threshold frequency increases the kinetic energy of photoelectrons.', 'The number of photoelectrons emitted depends on the intensity of light.', 3, '<p>A is false: the kinetic energy depends on the frequency (K = hν - φ), not on the intensity.</p><p>R is true: more photons per second eject more electrons. So A is false and R is true.</p>'),
    asr('as-061', 3, 'electronic configuration', 'The ground-state electronic configuration of copper is [Ar] 3d<sup>10</sup> 4s<sup>1</sup>.', 'Completely filled and half-filled subshells have no extra stability.', 2, '<p>A is true (Z = 29).</p><p>R is false: completely filled and half-filled subshells are extra stable because of symmetrical distribution and large exchange energy. That is why Cu and Cr are exceptions. So A is true, R is false.</p>'),
    asr('as-062', 3, 'orbitals', 'A 2s orbital is spherical in shape.', 'A 2s orbital has one radial node.', 1, '<p>Both are true. But the orbital is spherical because l = 0 (no angular dependence), not because it has a radial node. A radial node is also present in 3p, which is not spherical.</p><p>So R is true but does not explain A.</p>'),
    stm('as-063', 3, 'quantum numbers', 'The number of orbitals in the shell with principal quantum number n is n<sup>2</sup>.', 'The maximum number of electrons in an f subshell is 10.', 1, '<p>I is correct: (2l + 1) summed over l = 0 to n - 1 gives n<sup>2</sup>.</p><p>II is incorrect: the f subshell has 7 orbitals and holds 14 electrons. (10 is for d.)</p>'),
    stm('as-064', 3, 'orbital energy', 'In a lithium atom, the 2p orbital has lower energy than the 2s orbital.', 'In a hydrogen atom, the 2s and 2p orbitals have the same energy.', 2, '<p>I is incorrect: in a multi-electron atom the 2s electron penetrates closer to the nucleus, so it feels a greater effective nuclear charge and 2s &lt; 2p.</p><p>II is correct: in a one-electron atom the energy depends only on n.</p>', 'Energy depends on n only in one-electron species.'),
    stm('as-065', 3, 'photoelectric effect', 'The photoelectric effect cannot be explained by treating light as a classical wave.', 'The maximum kinetic energy of photoelectrons depends on the frequency of light but not on its intensity.', 0, '<p>Both are correct. A wave picture predicts that more intensity gives more energy per electron and that any frequency should work with enough time. Experiments show a threshold frequency and K<sub>max</sub> independent of intensity. Einstein\'s photon picture explains this.</p>'),
    mat('as-066', 2, 'subatomic particles', 'm1', 'Match each scientist in List I with the discovery in List II.', 'A-q, B-p, C-s, D-r', ['A-p, B-q, C-s, D-r', 'A-q, B-p, C-r, D-s', 'A-s, B-p, C-q, D-r'], '<p>Thomson: charge-to-mass ratio of the electron (q). Rutherford: the nucleus (p). Chadwick: the neutron (s). Millikan: the charge on the electron (r).</p>'),
    mat('as-067', 2, 'quantum numbers', 'm2', 'Match each quantum number in List I with what it describes in List II.', 'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-q, C-p, D-s', 'A-r, B-p, C-s, D-q'], '<p>n: size and energy (r). l: shape (p). m<sub>l</sub>: orientation (q). m<sub>s</sub>: spin (s).</p>'),
    nat('as-068', 2, 'quantum numbers', 'How many orbitals are present in the shell with n = 4?', 16, 0, '', '<p>Number of orbitals in a shell = n<sup>2</sup> = 16 (one 4s, three 4p, five 4d, seven 4f: 1 + 3 + 5 + 7 = 16).</p>'),
    nat('as-069', 3, 'Bohr model', 'A hydrogen atom in its ground state absorbs a photon of energy 12.09 eV and then returns to the ground state in all possible ways. How many different spectral lines can be emitted?', 3, 0, '', '<p>Level reached: -13.6 + 12.09 = -1.51 eV, which is -13.6 / 9, so n = 3.</p><p>From n = 3 the possible jumps are 3→2, 3→1 and 2→1: <b>3</b> lines.</p>'),
    nat('as-070', 3, 'Bohr model', 'A hydrogen atom in the n = 2 level absorbs a photon of energy 12 eV and is ionised. What is the kinetic energy of the free electron in eV?', 8.6, 0.05, 'eV', '<p>Energy needed to ionise from n = 2 is 3.4 eV.</p><p>Kinetic energy = 12 - 3.4 = <b>8.6 eV</b>.</p>', 'Use the level the electron is in, not 13.6 eV.'),
    nat('as-071', 3, 'Bohr model', 'The energy of the electron in the n = 4 level of He<sup>+</sup> is the same as the energy of the electron in which level n of hydrogen? Give n.', 2, 0, '', '<p>E ∝ Z<sup>2</sup>/n<sup>2</sup>. He<sup>+</sup>, n = 4: 4/16 = 1/4. Hydrogen: 1/n<sup>2</sup> = 1/4, so n = <b>2</b>.</p><p>(Both have E = -3.4 eV.)</p>'),
    mk('as-072', 3, 'orbitals and nodes', 'A 4f orbital has', '0 radial nodes and 3 angular nodes', ['3 radial nodes and 0 angular nodes', '1 radial node and 2 angular nodes', '0 radial nodes and 4 angular nodes'], '<p>Radial nodes = n - l - 1 = 4 - 3 - 1 = 0. Angular nodes = l = 3. Total = 3 = n - 1.</p>'),
    mk('as-073', 3, 'orbital shapes', 'Which d orbital has no nodal plane (it has two nodal cones instead)?', 'd<sub>z²</sub>', ['d<sub>xy</sub>', 'd<sub>x²-y²</sub>', 'd<sub>yz</sub>'], '<p>d<sub>xy</sub>, d<sub>yz</sub>, d<sub>xz</sub> have two nodal planes each (the coordinate planes). d<sub>x²-y²</sub> has two nodal planes that bisect the x and y axes.</p><p>d<sub>z²</sub> has its two angular nodes as <b>cones</b>, not planes.</p>', 'Every d orbital has 2 angular nodes, but not all of them are planes.'),
    nat('as-074', 3, 'photoelectric effect', 'Photons of energy 4 eV fall on two metals A and B with work functions 1.5 eV and 2.5 eV. Find the ratio of the stopping potential of A to that of B. Give the answer to 2 decimals.', 1.67, 0.01, '', '<p>V<sub>0</sub> = (hν - φ)/e. For A: 4 - 1.5 = 2.5 V. For B: 4 - 2.5 = 1.5 V.</p><p>Ratio = 2.5 / 1.5 = <b>1.67</b>.</p>', 'The ratio of work functions (2.5/1.5 flipped) is not the ratio of stopping potentials.'),
    asr('as-075', 3, 'de Broglie wavelength', 'An electron and a proton accelerated from rest through the same potential difference have different de Broglie wavelengths.', 'The electron and the proton have different masses.', 0, '<p>For a charge q through V, λ = h / √(2mqV). With the same |q| and V, λ ∝ 1/√m. So the lighter electron has the longer wavelength.</p><p>A is true because R is true (the mass difference is exactly the reason).</p>'),
    // ---------- Level 4 ----------
    nat('as-076', 4, 'spectral series', 'An electron in He<sup>+</sup> jumps from n = 3 to n = 2. What is the wavelength of the emitted photon, in nm? (R<sub>H</sub> = 1.097 × 10<sup>7</sup> m<sup>-1</sup>)', 164, 1, 'nm', '<p>For a hydrogen-like ion 1/λ = R Z<sup>2</sup> (1/n<sub>1</sub><sup>2</sup> - 1/n<sub>2</sub><sup>2</sup>).</p><p>1/λ = 1.097 × 10<sup>7</sup> × 4 × (1/4 - 1/9) = 1.097 × 10<sup>7</sup> × 4 × 0.1389 = 6.09 × 10<sup>6</sup> m<sup>-1</sup>.</p><p>λ = <b>164 nm</b> (one quarter of the H wavelength of 656 nm).</p>', 'Do not forget Z<sup>2</sup>.'),
    mk('as-077', 4, 'spectral series', 'The photon emitted when Li<sup>2+</sup> goes from n = 6 to n = 3 has the same wavelength as the photon emitted by a hydrogen atom in the transition', 'n = 2 to n = 1', ['n = 3 to n = 1', 'n = 3 to n = 2', 'n = 4 to n = 2'], '<p>Compare Z<sup>2</sup>(1/n<sub>1</sub><sup>2</sup> - 1/n<sub>2</sub><sup>2</sup>).</p><p>Li<sup>2+</sup>: 9 × (1/9 - 1/36) = 9 × 3/36 = 0.75.</p><p>H, 2→1: 1 - 1/4 = 0.75 ✓. (3→1 gives 0.889, 3→2 gives 0.139, 4→2 gives 0.188.)</p>', 'Z<sup>2</sup> times the term difference has to match, not each level.'),
    nat('as-078', 4, 'orbital angular momentum', 'The orbital angular momentum of an electron in a 3d orbital is compared with the Bohr angular momentum of the n = 3 orbit of hydrogen (3h/2π). Find the ratio of the first to the second. Give the answer to 2 decimals.', 0.82, 0.01, '', '<p>3d: l = 2, so L = √(l(l + 1)) h/2π = √6 h/2π = 2.449 h/2π.</p><p>Bohr: 3 h/2π.</p><p>Ratio = 2.449 / 3 = <b>0.82</b>.</p>', 'Bohr\'s model and wave mechanics give different values of angular momentum.'),
    nat('as-079', 4, 'de Broglie wavelength', 'In a hydrogen-like species, the de Broglie wavelength of the electron in the n = 2 orbit of H is λ<sub>1</sub>, and in the n = 1 orbit of He<sup>+</sup> it is λ<sub>2</sub>. Find λ<sub>1</sub>/λ<sub>2</sub>.', 4, 0, '', '<p>2πr = nλ, so λ = 2πr/n. With r ∝ n<sup>2</sup>/Z, λ ∝ n/Z.</p><p>H, n = 2: λ<sub>1</sub> ∝ 2/1 = 2. He<sup>+</sup>, n = 1: λ<sub>2</sub> ∝ 1/2.</p><p>Ratio = 2 / (1/2) = <b>4</b>.</p>'),
    nat('as-080', 4, 'photoelectric effect', 'Light of wavelength 300 nm produces a stopping potential of 1.2 V in a metal. What is the threshold wavelength of the metal, in nm? (hc = 1240 eV nm)', 423, 2, 'nm', '<p>Photon energy = 1240 / 300 = 4.133 eV.</p><p>φ = 4.133 - 1.2 = 2.933 eV.</p><p>λ<sub>0</sub> = 1240 / 2.933 = <b>423 nm</b>.</p>'),
    nat('as-081', 4, 'photoelectric effect', 'A student measures the stopping potential at two frequencies: 1.25 V at 8.0 × 10<sup>14</sup> Hz and 2.49 V at 11.0 × 10<sup>14</sup> Hz. Using eV<sub>0</sub> = hν - φ, find h in units of 10<sup>-34</sup> J s. (e = 1.6 × 10<sup>-19</sup> C)', 6.6, 0.1, '× 10<sup>-34</sup> J s', '<p>Subtract the two equations: e(V<sub>2</sub> - V<sub>1</sub>) = h(ν<sub>2</sub> - ν<sub>1</sub>).</p><p>h = 1.6 × 10<sup>-19</sup> × 1.24 / (3.0 × 10<sup>14</sup>) = 6.61 × 10<sup>-34</sup> J s.</p><p>So the answer is <b>6.6</b>. The slope of the V<sub>0</sub> versus ν graph is h/e.</p>', 'The slope of the graph is h/e, and the intercept gives the work function.'),
    nat('as-082', 4, 'spectral series', 'Find the ratio of the longest wavelength in the Balmer series to the longest wavelength in the Lyman series of hydrogen. Give the answer to 1 decimal place.', 5.4, 0.05, '', '<p>Longest Balmer: n = 3 → 2: 1/λ = R(1/4 - 1/9) = 5R/36, λ = 36/(5R).</p><p>Longest Lyman: n = 2 → 1: 1/λ = 3R/4, λ = 4/(3R).</p><p>Ratio = (36/5) × (3/4) = 27/5 = <b>5.4</b>.</p>'),
    nat('as-083', 4, 'mixed: moles and magnetism', 'How many moles of unpaired electrons are present in 5.6 g of Fe<sup>2+</sup> ions (Fe = 56, Z = 26), in the gaseous state? Give the answer as the number of moles.', 0.4, 0.005, 'mol', '<p>Moles of Fe<sup>2+</sup> = 5.6 / 56 = 0.1 mol (the mass of the lost electrons is negligible).</p><p>Each Fe<sup>2+</sup> is 3d<sup>6</sup> with 4 unpaired electrons.</p><p>Unpaired electrons = 0.1 × 4 = <b>0.4 mol</b>.</p>'),
    nat('as-084', 4, 'orbitals and nodes', 'An orbital has 2 radial nodes and 2 angular nodes. What is its principal quantum number?', 5, 0, '', '<p>Angular nodes = l = 2, so it is a d orbital.</p><p>Radial nodes = n - l - 1 = 2, so n = 2 + 2 + 1 = <b>5</b>. It is a 5d orbital.</p>'),
    nat('as-085', 4, 'Aufbau principle', 'What is the maximum number of electrons that can be present in all the orbitals for which (n + l) = 5?', 18, 0, '', '<p>(n + l) = 5 for 5s (5 + 0), 4p (4 + 1) and 3d (3 + 2).</p><p>Electrons: 2 + 6 + 10 = <b>18</b>.</p>'),
    nat('as-086', 4, 'Bohr model', 'Find the ratio of the time period of revolution of the electron in the n = 3 orbit of Li<sup>2+</sup> to that in the n = 1 orbit of H.', 3, 0, '', '<p>T = 2πr / v. With r ∝ n<sup>2</sup>/Z and v ∝ Z/n, T ∝ n<sup>3</sup>/Z<sup>2</sup>.</p><p>Li<sup>2+</sup>, n = 3: 27 / 9 = 3. H, n = 1: 1.</p><p>Ratio = <b>3</b>.</p>'),
    nat('as-087', 4, 'Bohr model', 'A hydrogen-like ion emits a photon of energy 108.8 eV when its electron falls from n = 3 to n = 1. What is its atomic number?', 3, 0, '', '<p>ΔE = 13.6 Z<sup>2</sup> (1 - 1/9) = 13.6 Z<sup>2</sup> × 8/9 = 12.09 Z<sup>2</sup>.</p><p>12.09 Z<sup>2</sup> = 108.8, so Z<sup>2</sup> = 9 and Z = <b>3</b> (Li<sup>2+</sup>).</p>'),
    mk('as-088', 4, 'electronic configuration', 'In the ion Cu<sup>2+</sup> (Z = 29), the electronic configuration and the number of unpaired electrons are', '[Ar] 3d<sup>9</sup>, 1', ['[Ar] 3d<sup>8</sup> 4s<sup>1</sup>, 2', '[Ar] 3d<sup>10</sup> 4s<sup>1</sup>, 1', '[Ar] 3d<sup>9</sup>, 3'], '<p>Cu is [Ar] 3d<sup>10</sup> 4s<sup>1</sup>. Removing two electrons: first the 4s electron, then one 3d electron. Cu<sup>2+</sup> = [Ar] 3d<sup>9</sup>.</p><p>3d<sup>9</sup> has four paired orbitals and one half-filled orbital: <b>1</b> unpaired electron.</p>', 'Cations lose the outermost (n highest) electrons first.'),
    asr('as-089', 4, 'Bohr model', 'The ionisation energy of He<sup>+</sup> is four times that of hydrogen.', 'In hydrogen-like species the energy of an electron in the nth level is proportional to Z<sup>2</sup>/n<sup>2</sup>.', 0, '<p>I.E. = 13.6 Z<sup>2</sup>. For He<sup>+</sup> (Z = 2): 54.4 eV; for H: 13.6 eV; ratio 4. Both are true and R is the reason.</p>'),
    asr('as-090', 4, 'Bohr model', 'Bohr\'s model correctly predicts the spectral lines of Li<sup>+</sup>.', 'Bohr\'s model is valid only for species that have a single electron.', 3, '<p>Li<sup>+</sup> has two electrons, so electron-electron repulsion makes Bohr\'s model fail. A is false.</p><p>R is true: the model works for H, He<sup>+</sup>, Li<sup>2+</sup> and similar one-electron species. So A is false and R is true.</p>'),
    stm('as-091', 4, 'spectral series', 'The first line of the Balmer series has a shorter wavelength than the second line.', 'The Balmer series lies completely in the ultraviolet region.', 3, '<p>I is incorrect: the first line (3→2, 656 nm) has the longest wavelength. The second line (4→2) is 486 nm.</p><p>II is incorrect: the Balmer series lies mostly in the visible region (656 nm to 410 nm for the first four lines); only lines near the limit (365 nm) are in the near-UV. The Lyman series is the UV one.</p>'),
    { id: 'as-092', type: 'mcq', level: 4, format: 'statements', exams: EX[4], sub: 'Bohr model', q: '<p>How many of the following statements about the nth Bohr orbit of a hydrogen-like species are correct?</p><ol><li>The radius is proportional to n<sup>2</sup>/Z.</li><li>The speed of the electron is proportional to n/Z.</li><li>The energy is proportional to -Z<sup>2</sup>/n<sup>2</sup>.</li><li>The frequency of revolution is proportional to Z<sup>2</sup>/n<sup>3</sup>.</li></ol>', options: ['1', '2', '3', '4'], answer: 2, sol: '<p>(1) True. (2) False: v ∝ Z/n, not n/Z. (3) True. (4) True: frequency = 1/T and T ∝ n<sup>3</sup>/Z<sup>2</sup>.</p><p>So three statements (1, 3, 4) are correct: <b>3</b>.</p>', trap: 'Speed falls as n grows; it rises with Z.' },
    mat('as-093', 4, 'orbitals and nodes', 'm3', 'Match each orbital in List I with its nodes in List II.', 'A-r, B-q, C-p, D-s', ['A-q, B-r, C-p, D-s', 'A-r, B-p, C-q, D-s', 'A-r, B-q, C-s, D-p'], '<p>Radial nodes = n - l - 1; angular nodes = l.</p><p>3s: 2 radial, 0 angular (r). 3p: 1 radial, 1 angular (q). 3d: 0 radial, 2 angular (p). 4s: 3 radial, 0 angular (s).</p>'),
    msq('as-094', 4, 'quantum numbers', 'Which of the following sets of quantum numbers (n, l, m<sub>l</sub>, m<sub>s</sub>) are permitted?', ['(3, 2, -2, +½)', '(2, 2, 0, +½)', '(4, 3, +3, -½)', '(3, 1, -2, +½)'], [0, 2], '<p>Rules: l = 0 to n - 1; m<sub>l</sub> = -l to +l; m<sub>s</sub> = ±½.</p><p>A: l = 2 &lt; 3, m<sub>l</sub> = -2 fine ✓. B: l = 2 is not less than n = 2 ✗. C: l = 3 &lt; 4, m<sub>l</sub> = +3 fine ✓. D: for l = 1, m<sub>l</sub> can only be -1, 0, +1, so -2 ✗.</p><p>Answer: A and C.</p>'),
    msq('as-095', 4, 'magnetic moment', 'Which of the following ions are diamagnetic? (Z: Sc 21, Fe 26, Cu 29, Zn 30)', ['Cu<sup>+</sup>', 'Zn<sup>2+</sup>', 'Sc<sup>3+</sup>', 'Fe<sup>2+</sup>'], [0, 1, 2], '<p>Cu<sup>+</sup> is 3d<sup>10</sup> ✓. Zn<sup>2+</sup> is 3d<sup>10</sup> ✓. Sc<sup>3+</sup> is [Ar] (no d electrons) ✓. Fe<sup>2+</sup> is 3d<sup>6</sup> with 4 unpaired electrons ✗.</p><p>Answer: A, B and C.</p>'),
    msq('as-096', 4, 'orbitals and nodes', 'Which statements are correct for a 3p orbital?', ['It has 1 radial node', 'It has 2 radial nodes', 'It has 1 angular node', 'It has 2 nodes in total'], [0, 2, 3], '<p>Radial nodes = n - l - 1 = 3 - 1 - 1 = 1. Angular nodes = l = 1. Total = 2.</p><p>So A, C and D are correct; B is wrong.</p>'),
    msq('as-097', 4, 'photoelectric effect', 'Which of the following are consistent with experiments on the photoelectric effect?', ['The maximum kinetic energy does not depend on the intensity of light', 'A minimum (threshold) frequency exists below which no emission occurs', 'The saturation current is proportional to the intensity of light', 'The stopping potential does not depend on the frequency of light', 'Emission starts almost instantly, even with very weak light'], [0, 1, 2, 4], '<p>A, B, C and E are all observed facts. D is wrong: the stopping potential increases linearly with frequency (eV<sub>0</sub> = hν - φ).</p><p>Answer: A, B, C and E.</p>'),
    msq('as-098', 4, 'Bohr model', 'For an electron in the nth orbit of a hydrogen atom, which statements are correct?', ['The radius is proportional to n<sup>2</sup>', 'The speed is proportional to 1/n', 'The total energy is proportional to 1/n', 'The kinetic energy is equal in magnitude to the total energy'], [0, 1, 3], '<p>r ∝ n<sup>2</sup> ✓. v ∝ 1/n ✓. E ∝ -1/n<sup>2</sup>, not 1/n ✗. KE = -E, equal in magnitude ✓.</p><p>Answer: A, B and D.</p>'),
    msq('as-099', 4, 'electronic configuration', 'Which of the following ground-state configurations are correct?', ['Zn: [Ar] 3d<sup>9</sup> 4s<sup>2</sup> 4p<sup>1</sup>', 'Cr: [Ar] 3d<sup>5</sup> 4s<sup>1</sup>', 'Fe: [Ar] 3d<sup>6</sup> 4s<sup>2</sup>', 'Cu: [Ar] 3d<sup>10</sup> 4s<sup>1</sup>'], [1, 2, 3], '<p>Zn (Z = 30) is [Ar] 3d<sup>10</sup> 4s<sup>2</sup>, so A is wrong. B and D are the well-known exceptions. C is regular.</p><p>Answer: B, C and D.</p>'),
    // ---------- Level 5 ----------
    nat('as-100', 5, 'Bohr model: reduced mass', 'Positronium is a hydrogen-like atom in which a positron (same mass as the electron, charge +e) replaces the proton. Using the Bohr model with reduced mass, what is the ionisation energy of ground-state positronium, in eV?', 6.8, 0.05, 'eV', '<p>Bohr energies are proportional to the reduced mass μ of the two particles.</p><p>For hydrogen μ ≈ m (proton is very heavy). For positronium μ = m × m / (m + m) = m/2.</p><p>Energy = 13.6 × ½ = <b>6.8 eV</b>.</p>', 'The nucleus is not "fixed" when it is as light as the electron.'),
    nat('as-101', 5, 'Bohr model: recoil', 'A hydrogen atom (mass 1.67 × 10<sup>-27</sup> kg) at rest in the n = 2 level emits a photon and drops to n = 1. Find the recoil speed of the atom in m s<sup>-1</sup>. (1 eV = 1.6 × 10<sup>-19</sup> J, c = 3 × 10<sup>8</sup> m s<sup>-1</sup>; ignore the tiny change in the photon energy)', 3.26, 0.05, 'm s<sup>-1</sup>', '<p>Photon energy = 13.6 - 3.4 = 10.2 eV = 1.632 × 10<sup>-18</sup> J.</p><p>Photon momentum = E/c = 1.632 × 10<sup>-18</sup> / 3 × 10<sup>8</sup> = 5.44 × 10<sup>-27</sup> kg m s<sup>-1</sup>.</p><p>The atom recoils with equal momentum: v = 5.44 × 10<sup>-27</sup> / 1.67 × 10<sup>-27</sup> = <b>3.26 m s<sup>-1</sup></b>.</p>', 'Conservation of momentum is used with the photon momentum E/c.'),
    nat('as-102', 5, 'photoelectric effect', 'A photon of wavelength 50 nm falls on a ground-state He<sup>+</sup> ion. What is the kinetic energy of the ejected electron in eV? Enter 0 if no electron is ejected. (hc = 1240 eV nm; ionisation energy of He<sup>+</sup> = 54.4 eV)', 0, 0, 'eV', '<p>Photon energy = 1240 / 50 = 24.8 eV, which is less than 54.4 eV.</p><p>So the photon cannot ionise He<sup>+</sup> from its ground state, and no electron is ejected. The kinetic energy is <b>0</b>.</p><p>It also cannot excite the ion, since the gaps in He<sup>+</sup> are 40.8 eV (n = 1 to 2), 48.4 eV (to 3) and so on, none equal to 24.8 eV.</p>', 'Check that the photon energy is enough before computing a kinetic energy.'),
    msq('as-103', 5, 'electronic configuration', 'Which of the following ground-state configurations are correct? (Z: Mo 42, Pd 46, Pt 78, Ag 47)', ['Mo: [Kr] 4d<sup>5</sup> 5s<sup>1</sup>', 'Pd: [Kr] 4d<sup>8</sup> 5s<sup>2</sup>', 'Pt: [Xe] 4f<sup>14</sup> 5d<sup>9</sup> 6s<sup>1</sup>', 'Ag: [Kr] 4d<sup>10</sup> 5s<sup>1</sup>'], [0, 2, 3], '<p>Mo: half-filled 4d and half-filled 5s ✓. Pd is [Kr] 4d<sup>10</sup> with an empty 5s, so B is wrong. Pt: [Xe] 4f<sup>14</sup> 5d<sup>9</sup> 6s<sup>1</sup> ✓. Ag: filled d like Cu ✓.</p><p>Answer: A, C and D.</p>', 'Pd is the second-period-style exception with no s electron at all.'),
    msq('as-104', 5, 'magnetic moment', 'Which of these gaseous ions have four unpaired electrons? (Z: Cr 24, Mn 25, Fe 26, Co 27, Ni 28)', ['Cr<sup>2+</sup>', 'Fe<sup>2+</sup>', 'Mn<sup>3+</sup>', 'Co<sup>2+</sup>', 'Ni<sup>2+</sup>'], [0, 1, 2], '<p>Cr<sup>2+</sup> is 3d<sup>4</sup>: 4 unpaired ✓. Fe<sup>2+</sup> is 3d<sup>6</sup>: 4 ✓. Mn<sup>3+</sup> is 3d<sup>4</sup>: 4 ✓. Co<sup>2+</sup> is 3d<sup>7</sup>: 3 ✗. Ni<sup>2+</sup> is 3d<sup>8</sup>: 2 ✗.</p><p>Answer: A, B and C.</p>'),
    stm('as-105', 5, 'orbital angular momentum', 'The orbital angular momentum of a 3d electron is 2 (h/2π).', 'The angular momentum of an electron in the third Bohr orbit is 3 (h/2π).', 2, '<p>I is incorrect: L = √(l(l + 1)) h/2π = √6 h/2π ≈ 2.45 h/2π for l = 2.</p><p>II is correct: Bohr\'s postulate mvr = nh/2π with n = 3.</p>', 'Quantum mechanics and Bohr give different angular momentum.'),
    nat('as-106', 5, 'mixed: moles and photons', 'A laser emits 6.626 × 10<sup>-3</sup> W of light of wavelength 500 nm. The number of moles of photons it emits in 1 hour is x × 10<sup>-4</sup>. Find x to 1 decimal place. (h = 6.626 × 10<sup>-34</sup> J s, c = 3 × 10<sup>8</sup> m s<sup>-1</sup>, N<sub>A</sub> = 6.022 × 10<sup>23</sup>)', 1, 0.05, '', '<p>Energy of one photon = hc/λ = 6.626 × 10<sup>-34</sup> × 3 × 10<sup>8</sup> / 5 × 10<sup>-7</sup> = 3.976 × 10<sup>-19</sup> J.</p><p>Energy in 1 hour = 6.626 × 10<sup>-3</sup> W × 3600 s = 23.85 J.</p><p>Photons = 23.85 / 3.976 × 10<sup>-19</sup> = 6.0 × 10<sup>19</sup>.</p><p>Moles = 6.0 × 10<sup>19</sup> / 6.022 × 10<sup>23</sup> = 9.96 × 10<sup>-5</sup> mol, so x ≈ <b>1.0</b>.</p>', 'Convert the hour to seconds and photons to moles at the end.'),
    nat('as-116', 5, 'quantum numbers', 'How many electrons in a ground-state chromium atom (Z = 24) have the magnetic quantum number m<sub>l</sub> = 0?', 12, 0, '', '<p>Cr: 1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup> 3d<sup>5</sup> 4s<sup>1</sup>.</p><p>Each s orbital has m<sub>l</sub> = 0. Each p and d subshell has exactly one orbital with m<sub>l</sub> = 0.</p><p>1s: 2, 2s: 2, 2p (m<sub>l</sub> = 0 orbital): 2, 3s: 2, 3p (one orbital): 2, 3d (one orbital, one electron because 3d<sup>5</sup> is half filled): 1, 4s: 1.</p><p>Total = 2 + 2 + 2 + 2 + 2 + 1 + 1 = <b>12</b>.</p>', 'Use the exceptional configuration of Cr, and count only the m<sub>l</sub> = 0 orbital of each subshell.'),
    nat('as-117', 5, 'Hund\'s rule', 'What is the maximum number of electrons in a ground-state manganese atom (Z = 25) that can have the same spin (all m<sub>s</sub> = +½, say)?', 15, 0, '', '<p>Mn: 1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup> 3d<sup>5</sup> 4s<sup>2</sup>.</p><p>Every filled orbital has one ↑ and one ↓. Singly occupied orbitals (by Hund) can all be ↑.</p><p>Orbitals: 1s, 2s, 3s, 4s (4) + 2p (3) + 3p (3) + 3d (5) = 15 orbitals, each with an ↑ electron.</p><p>So <b>15</b> electrons can share the same spin (the other 10 have the opposite spin).</p>'),
    nat('as-118', 5, 'photoelectric effect', 'Light of wavelength 250 nm falls on two metals. Metal A has threshold wavelength 400 nm and metal B has threshold wavelength 300 nm. Find the ratio of the stopping potential of A to that of B. Give the answer to 2 decimals. (hc = 1240 eV nm)', 2.25, 0.03, '', '<p>Photon energy = 1240 / 250 = 4.96 eV.</p><p>φ<sub>A</sub> = 1240 / 400 = 3.10 eV, so V<sub>A</sub> = 4.96 - 3.10 = 1.86 V.</p><p>φ<sub>B</sub> = 1240 / 300 = 4.133 eV, so V<sub>B</sub> = 4.96 - 4.133 = 0.827 V.</p><p>Ratio = 1.86 / 0.827 = <b>2.25</b>.</p>', 'Convert threshold wavelengths to work functions first.'),
    mk('as-119', 5, 'Bohr model: excitation', 'Hydrogen atoms in the ground state are bombarded by electrons of kinetic energy 12.5 eV. The maximum number of different spectral lines that can then be emitted is', '3', ['1', '6', '0'], '<p>An electron can lose <i>any part</i> of its energy in a collision, so the atom can be excited to any level whose gap from n = 1 is at most 12.5 eV.</p><p>Gaps from n = 1: n = 2: 10.2 eV; n = 3: 12.09 eV; n = 4: 12.75 eV (too large). So the highest level reached is n = 3.</p><p>From n = 3 the lines are 3→2, 3→1 and 2→1: <b>3</b> lines.</p><p>(A 12.5 eV <i>photon</i> would not be absorbed at all, because a photon must give its whole energy.)</p>', 'Electron collisions can transfer partial energy; photons must match exactly.'),
    nat('as-120', 5, 'mixed: photoelectron wavelength', 'A hydrogen atom in its ground state is hit by a photon of energy 20 eV and ionised. What is the de Broglie wavelength of the ejected electron, in Å? Use λ = 12.27/√K Å with K in eV. Give the answer to 2 decimals.', 4.85, 0.06, 'Å', '<p>Kinetic energy of the electron = 20 - 13.6 = 6.4 eV.</p><p>λ = 12.27 / √6.4 = 12.27 / 2.53 = <b>4.85 Å</b>.</p>', 'Subtract the ionisation energy before using the de Broglie formula.'),
    // ---------- Passages ----------
    PN('as-107', 3, 'Bohr model', 'p1', 'What is the atomic number Z of the ion?', 2, 0, '', '<p>E<sub>1</sub> = -13.6 Z<sup>2</sup> = -54.4 eV, so Z<sup>2</sup> = 4 and Z = <b>2</b>. The ion is He<sup>+</sup>.</p>'),
    PN('as-108', 3, 'Bohr model', 'p1', 'What is the energy of the electron in the n = 3 level of this ion, in eV? Give the answer to 2 decimals (include the sign).', -6.04, 0.05, 'eV', '<p>E<sub>3</sub> = E<sub>1</sub> / 9 = -54.4 / 9 = <b>-6.04 eV</b>.</p>'),
    PN('as-109', 4, 'Bohr model', 'p1', 'What is the wavelength of the photon emitted when the electron goes from n = 2 to n = 1, in nm?', 30.4, 0.3, 'nm', '<p>E<sub>2</sub> = -54.4 / 4 = -13.6 eV. ΔE = -13.6 - (-54.4) = 40.8 eV.</p><p>λ = 1240 / 40.8 = <b>30.4 nm</b>.</p>'),
    PN('as-110', 3, 'photoelectric effect', 'p2', 'What is the maximum kinetic energy of the photoelectrons, in eV?', 0.8, 0.02, 'eV', '<p>Photon energy = 1240 / 400 = 3.1 eV. K<sub>max</sub> = 3.1 - 2.3 = <b>0.8 eV</b>.</p>'),
    PN('as-111', 3, 'photoelectric effect', 'p2', 'What is the threshold wavelength for this metal, in nm?', 539, 2, 'nm', '<p>λ<sub>0</sub> = hc/φ = 1240 / 2.3 = <b>539 nm</b>.</p>'),
    PN('as-112', 4, 'photoelectric effect', 'p2', 'The maximum speed of the fastest photoelectrons is x × 10<sup>5</sup> m s<sup>-1</sup>. Find x to 1 decimal place.', 5.3, 0.1, '', '<p>K = 0.8 eV = 0.8 × 1.6 × 10<sup>-19</sup> = 1.28 × 10<sup>-19</sup> J.</p><p>v = √(2K/m) = √(2 × 1.28 × 10<sup>-19</sup> / 9.1 × 10<sup>-31</sup>) = √(2.81 × 10<sup>11</sup>) = 5.3 × 10<sup>5</sup> m s<sup>-1</sup>. So x = <b>5.3</b>.</p>'),
    PN('as-113', 3, 'magnetic moment', 'p3', 'How many unpaired electrons are present in Fe<sup>3+</sup>?', 5, 0, '', '<p>Fe<sup>3+</sup> = [Ar] 3d<sup>5</sup>: five electrons in five orbitals, all parallel: <b>5</b> unpaired.</p>'),
    PN('as-114', 3, 'magnetic moment', 'p3', 'What is the spin-only magnetic moment of Fe<sup>3+</sup> in BM? Give the answer to 2 decimals.', 5.92, 0.02, 'BM', '<p>μ = √(n(n + 2)) = √(5 × 7) = √35 = <b>5.92 BM</b>.</p>'),
    P('as-115', 4, 'magnetic moment', 'p3', 'Which statement about the two ions is correct?', 'Fe<sup>3+</sup> is more paramagnetic: 5.92 BM against 4.90 BM for Fe<sup>2+</sup>', ['Fe<sup>2+</sup> is more paramagnetic because it has more electrons', 'Both have the same magnetic moment because both are 3d ions', 'Fe<sup>2+</sup> is more paramagnetic: 5.92 BM against 4.90 BM for Fe<sup>3+</sup>'], '<p>Fe<sup>2+</sup> is 3d<sup>6</sup> with 4 unpaired electrons: μ = √24 = 4.90 BM. Fe<sup>3+</sup> is 3d<sup>5</sup> with 5 unpaired electrons: μ = √35 = 5.92 BM.</p><p>The magnetic moment depends on the number of <i>unpaired</i> electrons, not on the number of electrons. So Fe<sup>3+</sup> is more paramagnetic.</p>', 'Losing an electron made it more paramagnetic here (pairing is removed).'),
  ],
  gens: [
    { id: 'as-g01', type: 'nat', level: 2, exams: EX[2], sub: 'Bohr model',
      make(rng) {
        const Z = choose(rng, [1, 2, 3]), n = int(rng, 1, 4); const sp = { 1: 'H', 2: 'He<sup>+</sup>', 3: 'Li<sup>2+</sup>' }[Z];
        const r = 0.529 * n * n / Z;
        return { q: `What is the radius of the n = ${n} Bohr orbit of ${sp}, in Å? (a<sub>0</sub> = 0.529 Å)`, answer: +r.toFixed(4), tol: +(r * 0.01 + 0.001).toFixed(4), unit: 'Å', Z, n,
          sol: `<p>r<sub>n</sub> = a<sub>0</sub> n<sup>2</sup> / Z = 0.529 × ${n}<sup>2</sup> / ${Z}.</p><p>r = 0.529 × ${n * n} / ${Z} = <b>${fmt(r, 4)} Å</b>.</p>` };
      }, verify: (p) => 0.529 * p.n ** 2 / p.Z },
    { id: 'as-g02', type: 'nat', level: 2, exams: EX[2], sub: 'Bohr model',
      make(rng) {
        const Z = choose(rng, [1, 2, 3]), n = int(rng, 1, 5); const sp = { 1: 'H', 2: 'He<sup>+</sup>', 3: 'Li<sup>2+</sup>' }[Z];
        const E = -13.6 * Z * Z / (n * n);
        return { q: `What is the energy of the electron in the n = ${n} level of ${sp}, in eV? (Include the sign.)`, answer: +E.toFixed(4), tol: +(Math.abs(E) * 0.01 + 0.005).toFixed(4), unit: 'eV', Z, n,
          sol: `<p>E<sub>n</sub> = -13.6 Z<sup>2</sup> / n<sup>2</sup> eV = -13.6 × ${Z * Z} / ${n * n}.</p><p>E = <b>${fmt(E, 4)} eV</b>.</p>`, trap: 'Z is squared and n is squared.' };
      }, verify: (p) => -13.6 * (p.Z / p.n) ** 2 },
    { id: 'as-g03', type: 'nat', level: 2, exams: EX[2], sub: 'spectral lines',
      make(rng) {
        const n = int(rng, 3, 8);
        return { q: `Hydrogen atoms are excited to the n = ${n} level. What is the maximum number of different spectral lines that can be emitted as they return to lower levels?`, answer: n * (n - 1) / 2, tol: 0, n,
          sol: `<p>Number of lines = n(n - 1)/2 = ${n} × ${n - 1} / 2 = <b>${n * (n - 1) / 2}</b>.</p><p>(This counts every pair of levels, so all series are included.)</p>` };
      }, verify: (p) => { let c = 0; for (let a = 1; a <= p.n; a++) for (let b = a + 1; b <= p.n; b++) c++; return c; } },
    { id: 'as-g04', type: 'nat', level: 2, exams: EX[2], sub: 'electromagnetic radiation',
      make(rng) {
        const l = choose(rng, [200, 248, 310, 400, 496, 620, 800]);
        const E = 1240 / l;
        return { q: `What is the energy of a photon of wavelength ${l} nm, in eV? (hc = 1240 eV nm)`, answer: +E.toFixed(4), tol: +(E * 0.01).toFixed(4), unit: 'eV', l,
          sol: `<p>E = hc/λ = 1240 / ${l} = <b>${fmt(E, 4)} eV</b>.</p>` };
      }, verify: (p) => 6.626e-34 * 3e8 / (p.l * 1e-9) / 1.6e-19 },
    { id: 'as-g05', type: 'nat', level: 3, exams: EX[3], sub: 'photoelectric effect',
      make(rng) {
        const l = choose(rng, [150, 200, 220, 250, 300]); const phi = pick(rng, 1.8, 4.2, 0.2);
        const K = 1240 / l - phi; if (K < 0.3) return this.make(rng);
        return { q: `Light of wavelength ${l} nm falls on a metal with work function ${phi} eV. What is the maximum kinetic energy of the photoelectrons, in eV? (hc = 1240 eV nm)`, answer: +K.toFixed(4), tol: +(K * 0.01 + 0.005).toFixed(4), unit: 'eV', l, phi,
          sol: `<p>Photon energy = 1240 / ${l} = ${fmt(1240 / l, 4)} eV.</p><p>K<sub>max</sub> = hν - φ = ${fmt(1240 / l, 4)} - ${phi} = <b>${fmt(K, 4)} eV</b>.</p>` };
      }, verify: (p) => 1240 / p.l - p.phi },
    { id: 'as-g06', type: 'nat', level: 3, exams: EX[3], sub: 'de Broglie wavelength',
      make(rng) {
        const V = choose(rng, [25, 64, 100, 150, 225, 400, 900]);
        const lam = 12.27 / Math.sqrt(V);
        return { q: `An electron is accelerated from rest through a potential difference of ${V} V. What is its de Broglie wavelength, in Å? (Use λ = h/√(2meV); you may use λ = 12.27/√V Å.)`, answer: +lam.toFixed(4), tol: +(lam * 0.015).toFixed(4), unit: 'Å', V,
          sol: `<p>λ = 12.27 / √V = 12.27 / √${V} = 12.27 / ${Math.sqrt(V)} = <b>${fmt(lam, 4)} Å</b>.</p>` };
      }, verify: (p) => 6.626e-34 / Math.sqrt(2 * 9.1e-31 * 1.6e-19 * p.V) * 1e10 },
    { id: 'as-g07', type: 'nat', level: 2, exams: EX[2], sub: 'orbitals and nodes',
      make(rng) {
        const n = int(rng, 2, 6); const l = int(rng, 0, Math.min(n - 1, 3)); const L = 'spdf'[l];
        const ask = choose(rng, ['radial', 'total']);
        const ans = ask === 'radial' ? n - l - 1 : n - 1;
        return { q: `How many ${ask} nodes does a ${n}${L} orbital have?`, answer: ans, tol: 0, n, l, ask,
          sol: ask === 'radial' ? `<p>Radial nodes = n - l - 1 = ${n} - ${l} - 1 = <b>${ans}</b>.</p>` : `<p>Radial nodes = ${n - l - 1}; angular nodes = l = ${l}. Total = n - 1 = <b>${ans}</b>.</p>` };
      }, verify: (p) => p.ask === 'radial' ? p.n - p.l - 1 : (p.n - p.l - 1) + p.l },
    { id: 'as-g08', type: 'nat', level: 3, exams: EX[3], sub: 'magnetic moment',
      make(rng) {
        const ion = choose(rng, [['Ti<sup>3+</sup>', 'Ti [Ar] 3d<sup>2</sup> 4s<sup>2</sup>', '3d<sup>1</sup>', 1], ['V<sup>3+</sup>', 'V [Ar] 3d<sup>3</sup> 4s<sup>2</sup>', '3d<sup>2</sup>', 2], ['Cr<sup>3+</sup>', 'Cr [Ar] 3d<sup>5</sup> 4s<sup>1</sup>', '3d<sup>3</sup>', 3], ['Cr<sup>2+</sup>', 'Cr [Ar] 3d<sup>5</sup> 4s<sup>1</sup>', '3d<sup>4</sup>', 4], ['Mn<sup>2+</sup>', 'Mn [Ar] 3d<sup>5</sup> 4s<sup>2</sup>', '3d<sup>5</sup>', 5], ['Fe<sup>2+</sup>', 'Fe [Ar] 3d<sup>6</sup> 4s<sup>2</sup>', '3d<sup>6</sup>', 4], ['Co<sup>2+</sup>', 'Co [Ar] 3d<sup>7</sup> 4s<sup>2</sup>', '3d<sup>7</sup>', 3], ['Ni<sup>2+</sup>', 'Ni [Ar] 3d<sup>8</sup> 4s<sup>2</sup>', '3d<sup>8</sup>', 2], ['Cu<sup>2+</sup>', 'Cu [Ar] 3d<sup>10</sup> 4s<sup>1</sup>', '3d<sup>9</sup>', 1], ['Zn<sup>2+</sup>', 'Zn [Ar] 3d<sup>10</sup> 4s<sup>2</sup>', '3d<sup>10</sup>', 0]]);
        const nd = +ion[2].replace(/3d<sup>(\d+)<\/sup>/, '$1'); const unp = nd <= 5 ? nd : 10 - nd;
        return { q: `How many unpaired electrons does the ion ${ion[0]} have in the gaseous state?`, answer: unp, tol: 0, nd,
          sol: `<p>Neutral atom: ${ion[1]}. The cation loses 4s electrons first (and then 3d if needed), so ${ion[0]} is [Ar] ${ion[2]}.</p><p>d electrons: ${nd}. Fill the five d orbitals singly first, then pair: unpaired = <b>${unp}</b>.</p>` };
      }, verify: (p) => (p.nd <= 5 ? p.nd : 10 - p.nd) },
    { id: 'as-g09', type: 'nat', level: 2, exams: EX[2], sub: 'magnetic moment',
      make(rng) {
        const nn = int(rng, 1, 5); const mu = Math.sqrt(nn * (nn + 2));
        return { q: `An ion has ${nn} unpaired electron${nn > 1 ? 's' : ''}. What is its spin-only magnetic moment, in Bohr magnetons (BM)? Give 2 decimals.`, answer: +mu.toFixed(2), tol: 0.02, unit: 'BM', nn,
          sol: `<p>μ = √(n(n + 2)) = √(${nn} × ${nn + 2}) = √${nn * (nn + 2)} = <b>${fmt(mu, 3)} BM</b>.</p>` };
      }, verify: (p) => Math.sqrt(p.nn ** 2 + 2 * p.nn) },
    { id: 'as-g10', type: 'nat', level: 3, exams: EX[3], sub: 'Bohr model',
      make(rng) {
        const Z = choose(rng, [1, 2, 3]), n = int(rng, 1, 4); const sp = { 1: 'H', 2: 'He<sup>+</sup>', 3: 'Li<sup>2+</sup>' }[Z];
        const v = 2.18 * Z / n;
        return { q: `What is the speed of the electron in the n = ${n} orbit of ${sp}, in units of 10<sup>6</sup> m s<sup>-1</sup>? (Speed in the first orbit of H = 2.18 × 10<sup>6</sup> m s<sup>-1</sup>)`, answer: +v.toFixed(4), tol: +(v * 0.01 + 0.005).toFixed(4), unit: '× 10<sup>6</sup> m s<sup>-1</sup>', Z, n,
          sol: `<p>v<sub>n</sub> = 2.18 × 10<sup>6</sup> × Z/n = 2.18 × ${Z} / ${n} × 10<sup>6</sup> = <b>${fmt(v, 4)} × 10<sup>6</sup> m s<sup>-1</sup></b>.</p>` };
      }, verify: (p) => 2.18 * (p.Z / p.n) },
    { id: 'as-g11', type: 'mcq', level: 2, exams: EX[2], sub: 'quantum numbers',
      make(rng) {
        const txt = (s) => `(${s[0]}, ${s[1]}, ${s[2] > 0 ? '+' + s[2] : s[2]}, ${s[3] === 0.5 ? '+½' : s[3] === -0.5 ? '-½' : s[3] > 0 ? '+' + s[3] : s[3]})`;
        const good = () => { const n = int(rng, 2, 4), l = int(rng, 0, n - 1), ml = int(rng, -l, l); return [n, l, ml, choose(rng, [0.5, -0.5])]; };
        const defect = int(rng, 0, 2);
        let bad = good(); if (defect === 0) bad = [bad[0], bad[0], 0, bad[3]]; else if (defect === 1) { bad = [bad[0], bad[1], bad[1] + 1, bad[3]]; } else bad = [bad[0], bad[1], bad[2], choose(rng, [1, 0])];
        let sets, seen; do { sets = [good(), good(), good()]; seen = new Set([...sets, bad].map(txt)); } while (seen.size < 4);
        const all = [bad, ...sets]; for (let i = all.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [all[i], all[j]] = [all[j], all[i]]; }
        const why = defect === 0 ? `l must be less than n, but here l = n = ${bad[0]}` : defect === 1 ? `for l = ${bad[1]}, m<sub>l</sub> can only go from -${bad[1]} to +${bad[1]}, not ${bad[2]}` : `m<sub>s</sub> can only be +½ or -½, not ${bad[3]}`;
        return { q: 'Which set of quantum numbers (n, l, m<sub>l</sub>, m<sub>s</sub>) is NOT possible for an electron?', options: all.map(txt), answer: all.indexOf(bad), sets: all,
          sol: `<p>Rules: l = 0 to n - 1; m<sub>l</sub> = -l to +l; m<sub>s</sub> = +½ or -½.</p><p>The set ${txt(bad)} breaks a rule: ${why}. The other three obey all three rules.</p>`, trap: 'Check all four numbers, one rule at a time.' };
      }, verify: (p) => p.sets.findIndex(([n, l, ml, ms]) => !(l >= 0 && l < n && Math.abs(ml) <= l && (ms === 0.5 || ms === -0.5))) },
    { id: 'as-g12', type: 'nat', level: 3, exams: EX[3], sub: 'spectral series',
      make(rng) {
        const Z = choose(rng, [1, 2, 3]); const [a, b] = choose(rng, [[1, 2], [1, 3], [2, 3], [2, 4], [3, 4], [2, 5]]);
        const sp = { 1: 'H', 2: 'He<sup>+</sup>', 3: 'Li<sup>2+</sup>' }[Z];
        const inv = 1.097e7 * Z * Z * (1 / (a * a) - 1 / (b * b)); const lam = 1e9 / inv;
        return { q: `Find the wavelength of the photon emitted when the electron in ${sp} falls from n = ${b} to n = ${a}, in nm. (R<sub>H</sub> = 1.097 × 10<sup>7</sup> m<sup>-1</sup>)`, answer: +lam.toFixed(2), tol: +(lam * 0.01).toFixed(2), unit: 'nm', Z, a, b,
          sol: `<p>1/λ = R Z<sup>2</sup> (1/${a}<sup>2</sup> - 1/${b}<sup>2</sup>) = 1.097 × 10<sup>7</sup> × ${Z * Z} × ${fmt(1 / (a * a) - 1 / (b * b), 4)} = ${fmt(inv, 4)} m<sup>-1</sup>.</p><p>λ = <b>${fmt(lam, 4)} nm</b>.</p>` };
      }, verify: (p) => 1e9 / (1.097e7 * p.Z ** 2 * (1 / p.a ** 2 - 1 / p.b ** 2)) },
    { id: 'as-g13', type: 'nat', level: 3, exams: EX[3], sub: 'photoelectric effect',
      make(rng) {
        const phi = choose(rng, [1.9, 2.3, 2.8, 3.1, 4.1, 4.5]);
        const l = 1240 / phi;
        return { q: `The work function of a metal is ${phi} eV. What is the threshold wavelength for the photoelectric effect, in nm? (hc = 1240 eV nm)`, answer: +l.toFixed(1), tol: +(l * 0.01).toFixed(1), unit: 'nm', phi,
          sol: `<p>λ<sub>0</sub> = hc/φ = 1240 / ${phi} = <b>${fmt(l, 4)} nm</b>. Light of longer wavelength (lower energy) cannot eject electrons.</p>` };
      }, verify: (p) => 6.626e-34 * 3e8 / (p.phi * 1.6e-19) * 1e9 },
    { id: 'as-g14', type: 'nat', level: 3, exams: EX[3], sub: 'electronic configuration',
      make(rng) {
        const Z = choose(rng, [9, 11, 13, 15, 16, 17, 20, 24, 25, 26, 29, 30]);
        const ask = choose(rng, ['p', 'd']); const L = { p: 1, d: 2 }[ask];
        const order = [['1s', 2, 0], ['2s', 2, 0], ['2p', 6, 1], ['3s', 2, 0], ['3p', 6, 1], ['4s', 2, 0], ['3d', 10, 2]];
        let left = Z; const occ = {};
        if (Z === 24) { Object.assign(occ, { '3d': 5, '4s': 1 }); left = Z - 6; } else if (Z === 29) { Object.assign(occ, { '3d': 10, '4s': 1 }); left = Z - 11; }
        const exc = Z === 24 || Z === 29;
        for (const [nm, cap] of (exc ? order.filter(([n]) => !['3d', '4s'].includes(n)) : order)) { const k = Math.min(cap, left); occ[nm] = k; left -= k; }
        const ans = Object.entries(occ).filter(([nm]) => nm[1] === ask).reduce((s, [, k]) => s + k, 0);
        const cfg = order.filter(([nm]) => occ[nm]).map(([nm]) => `${nm}<sup>${occ[nm]}</sup>`).join(' ');
        return { q: `How many electrons in a neutral atom of atomic number ${Z} have azimuthal quantum number l = ${L} (${ask} electrons)?`, answer: ans, tol: 0, Z, ask,
          sol: `<p>Write the ground-state configuration${exc ? ' (this is an exception: a half-filled or full d subshell is favoured)' : ''}: ${cfg}.</p><p>Count the ${ask} subshells: <b>${ans}</b>.</p>` };
      }, verify: (p) => { const Z = p.Z; if (p.ask === 'p') return Z <= 4 ? 0 : Z <= 10 ? Z - 4 : Z <= 12 ? 6 : Z <= 18 ? 6 + (Z - 12) : 12; if (Z === 24) return 5; if (Z === 29) return 10; return Z <= 20 ? 0 : Z - 20; } },
    { id: 'as-g15', type: 'nat', level: 3, exams: EX[3], sub: 'de Broglie wavelength',
      make(rng) {
        const k = int(rng, 1, 8); const v = k * 1e6; const lam = 6.626e-34 / (9.1e-31 * v) * 1e10;
        return { q: `An electron moves at ${k} × 10<sup>6</sup> m s<sup>-1</sup>. What is its de Broglie wavelength, in Å? (h = 6.626 × 10<sup>-34</sup> J s, m = 9.1 × 10<sup>-31</sup> kg)`, answer: +lam.toFixed(3), tol: +(lam * 0.01).toFixed(3), unit: 'Å', k,
          sol: `<p>λ = h/(mv) = 6.626 × 10<sup>-34</sup> / (9.1 × 10<sup>-31</sup> × ${k} × 10<sup>6</sup>) = ${fmt(lam / 1e10, 4)} m = <b>${fmt(lam, 4)} Å</b>.</p>` };
      }, verify: (p) => 6.626e-34 / (9.1e-31 * p.k * 1e6) * 1e10 },
    { id: 'as-g16', type: 'nat', level: 3, exams: EX[3], sub: 'electromagnetic radiation',
      make(rng) {
        const P = int(rng, 1, 5) * 20; const l = choose(rng, [400, 500, 600, 662.6]);
        const N = P * l * 1e-9 / (6.626e-34 * 3e8) / 1e19;
        return { q: `A source of power ${P} W emits light of wavelength ${l} nm only. How many photons does it emit per second, in units of 10<sup>19</sup>? (h = 6.626 × 10<sup>-34</sup> J s, c = 3 × 10<sup>8</sup> m s<sup>-1</sup>)`, answer: +N.toFixed(3), tol: +(N * 0.01).toFixed(3), unit: '× 10<sup>19</sup>', P, l,
          sol: `<p>Photon energy = hc/λ = 6.626 × 10<sup>-34</sup> × 3 × 10<sup>8</sup> / (${l} × 10<sup>-9</sup>) = ${fmt(6.626e-34 * 3e8 / (l * 1e-9), 4)} J.</p><p>Photons per second = ${P} / ${fmt(6.626e-34 * 3e8 / (l * 1e-9), 4)} = <b>${fmt(N, 4)} × 10<sup>19</sup></b>.</p>` };
      }, verify: (p) => p.P / (6.626e-34 * 3e8 / (p.l * 1e-9)) / 1e19 },
    { id: 'as-g17', type: 'nat', level: 4, exams: EX[4], sub: 'uncertainty principle',
      make(rng) {
        const dx = choose(rng, [0.5, 1, 2, 5]); const dv = 6.626e-34 / (4 * Math.PI * 9.1e-31 * dx * 1e-10) / 1e5;
        return { q: `The position of an electron is known to within ${dx} Å. What is the minimum uncertainty in its speed, in units of 10<sup>5</sup> m s<sup>-1</sup>? (Δx · Δp ≥ h/4π, h = 6.626 × 10<sup>-34</sup> J s, m = 9.1 × 10<sup>-31</sup> kg)`, answer: +dv.toFixed(3), tol: +(dv * 0.015).toFixed(3), unit: '× 10<sup>5</sup> m s<sup>-1</sup>', dx,
          sol: `<p>Δv ≥ h / (4π m Δx) = 6.626 × 10<sup>-34</sup> / (4π × 9.1 × 10<sup>-31</sup> × ${dx} × 10<sup>-10</sup>).</p><p>Δv = <b>${fmt(dv, 4)} × 10<sup>5</sup> m s<sup>-1</sup></b>.</p>`, trap: 'Convert Å to metres: 1 Å = 10<sup>-10</sup> m.' };
      }, verify: (p) => 6.626e-34 / (4 * Math.PI * 9.1e-31 * p.dx * 1e-10) / 1e5 },
  ],
};
